mapper.select:
SELECT * FROM payment_refund
WHERE deleted = FALSE
AND transaction_id = #{query.transactionId}
AND intent_id = #{query.intentId}
AND provider = #{query.provider}
AND status = #{query.status}
AND source_type = #{query.sourceType}
AND source_id = #{query.sourceId}

    AND (refund_no ILIKE CONCAT('%', #{query.keyword}, '%')
     OR provider_refund_no ILIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY created_at DESC, id DESC
